/** Black overlay colours keyed by alpha percent. */
export const scrim = {
  12: "rgba(0,0,0,0.12)",
  18: "rgba(0,0,0,0.18)",
  25: "rgba(0,0,0,0.25)",
  50: "rgba(0,0,0,0.5)",
